#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node
{
    int data;
    struct Node *left;
    struct Node *right;
};

// Function to create a new node
struct Node *createNode(int x)
{
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    newNode->data = x;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to find the height of the tree
int getHeight(struct Node *root, int h)
{
    if (root == NULL)
        return h - 1;
    int leftHeight = getHeight(root->left, h + 1);
    int rightHeight = getHeight(root->right, h + 1);
    return (leftHeight > rightHeight) ? leftHeight : rightHeight;
}

// Queue structure for level order traversal
struct QueueNode
{
    struct Node *node;
    int level;
};

struct Queue
{
    struct QueueNode arr[100];
    int front, rear;
};

// Initialize queue
void initQueue(struct Queue *q)
{
    q->front = 0;
    q->rear = 0;
}

// Enqueue
void enqueue(struct Queue *q, struct Node *node, int level)
{
    q->arr[q->rear].node = node;
    q->arr[q->rear].level = level;
    q->rear++;
}

// Dequeue
struct QueueNode dequeue(struct Queue *q)
{
    return q->arr[q->front++];
}

// Check if queue is empty
int isEmpty(struct Queue *q)
{
    return q->front == q->rear;
}

// Function to print Level Order Traversal
void levelOrder(struct Node *root)
{
    if (root == NULL)
        return;

    struct Queue q;
    initQueue(&q);
    enqueue(&q, root, 0);

    int lastLevel = 0;

    // function to get height of the tree
    int height = getHeight(root, 0);

    // printing level order of the tree
    while (!isEmpty(&q))
    {
        struct QueueNode temp = dequeue(&q);
        struct Node *node = temp.node;
        int lvl = temp.level;

        if (lvl > lastLevel)
        {
            printf("
");
            lastLevel = lvl;
        }

        // all levels are printed
        if (lvl > height)
            break;

        // Printing null nodes
        if (node->data != -1)
            printf("%d ", node->data);
        else
            printf("N ");

        // null node has no children
        if (node->data == -1)
            continue;

        if (node->left == NULL)
            enqueue(&q, createNode(-1), lvl + 1);
        else
            enqueue(&q, node->left, lvl + 1);

        if (node->right == NULL)
            enqueue(&q, createNode(-1), lvl + 1);
        else
            enqueue(&q, node->right, lvl + 1);
    }
}

